package greeter

import "strings"

// Slug 把名字转成 URL 友好的锚点 slug：统一小写、空白折成连字符、首尾不留。
func Slug(name string) string {
	return strings.Join(strings.Fields(strings.ToLower(name)), "-")
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"mixed case", "Ada Lovelace", "ada-lovelace"},
		{"collapse and trim", "  Ada   Lovelace  ", "ada-lovelace"},
		{"single word", "Ada", "ada"},
		{"empty", "", ""},
		{"blank", "   ", ""},
		{"tabs and newlines", "Hello\tWorld\n", "hello-world"},
	}
	for _, tt := range tests {
		if got := Slug(tt.in); got != tt.want {
			t.Errorf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
		}
	}
}

